 public sealed class JoinedTerrainScope {public readonly double MinX,MinZ,MaxX,MaxZ;public bool SourceSubsetOnly=>true;readonly string[] sourceIds;internal JoinedTerrainScope(double x,double z,string[] ids){MinX=x;MinZ=z;MaxX=x+32;MaxZ=z+32;sourceIds=(string[])ids.Clone();}public string[] CopySourceIds()=>(string[])sourceIds.Clone();}
