   BigInteger Orient(int a,int b,int c)=>(BigInteger)(xy[b].X-xy[a].X)*(xy[c].Z-xy[a].Z)-(BigInteger)(xy[b].Z-xy[a].Z)*(xy[c].X-xy[a].X);
   foreach(var packet in road.Concat(terrain)){cancellation.ThrowIfCancellationRequested();bool isRoad=members.ContainsKey(packet.Id);if(packet.XYZ.Length%3!=0||packet.Indices.Length%3!=0||packet.XYZ.Length>750000||packet.Indices.Length>1500000)throw new ArgumentException("Joined buffer budget");var remap=new int[packet.XYZ.Length/3];for(int i=0;i<remap.Length;i++){double x=packet.OriginX+packet.XYZ[i*3]-scope.MinX,z=packet.OriginZ+packet.XYZ[i*3+2]-scope.MinZ,y=packet.OriginY+packet.XYZ[i*3+1];if(!TerrainFieldLimits.Finite(x)||!TerrainFieldLimits.Finite(y)||!TerrainFieldLimits.Finite(z)||x<0||x>32||z<0||z>32)throw new ArgumentException("Joined nonfinite/outside scoped buffers");long xx=(long)Math.Round(x*scale),zz=(long)Math.Round(z*scale);if((double)xx/scale!=x||(double)zz/scale!=z)throw new ArgumentException("Joined noncanonical finalXZ");var key=(xx,zz);if(welded.TryGetValue(key,out int id)){if(yy[id]!=y)throw new ArgumentException("Joined duplicateXZ has DIFFERENT actualworldY; no seamgap admitted");}else{if(xy.Count>=250000)throw new ArgumentException("Joined totalvertexcap");id=xy.Count;welded.Add(key,id);xy.Add(key);yy.Add(y);}remap[i]=id;if(isRoad){if(!source.Pavement(scope.MinX+x,scope.MinZ+z,out double actual,out _,out _)||Math.Abs(actual-y)>.00002)throw new ArgumentException("Joined asphalt lacks bounded originalsource-plane support");}}
    for(int i=0;i<packet.Indices.Length;i+=3){if(++triangles>500000)throw new ArgumentException("Joined totaltrianglecap");int a=packet.Indices[i],b=packet.Indices[i+1],c=packet.Indices[i+2];if(a<0||b<0||c<0||a>=remap.Length||b>=remap.Length||c>=remap.Length)throw new ArgumentException("Joined finalindex invalid");a=remap[a];b=remap[b];c=remap[c];var area=Orient(a,b,c);if(area.Sign>=0)throw new ArgumentException("Joined zero/backward face cannot be dropped");totalArea-=area;double ux=(double)(xy[b].X-xy[a].X)/scale,uz=(double)(xy[b].Z-xy[a].Z)/scale,vx=(double)(xy[c].X-xy[a].X)/scale,vz=(double)(xy[c].Z-xy[a].Z)/scale,den=ux*vz-uz*vx,gx=((yy[b]-yy[a])*vz-(yy[c]-yy[a])*uz)/den,gz=(ux*(yy[c]-yy[a])-vx*(yy[b]-yy[a]))/den;if(Math.Sqrt(gx*gx+gz*gz)>1.200001)throw new ArgumentException("Joined finalface exceeds strict1.2grade; noflattening");foreach(var t in new[]{(a,b,c),(b,c,a),(c,a,b)}){var edge=new Edge(t.Item1,t.Item2);if(!adjacency.TryGetValue(edge,out var list))adjacency[edge]=list=new List<(int,int,int,string)>();list.Add((t.Item1,t.Item2,t.Item3,packet.Id+"/triangle/"+(i/3)));if(list.Count>2)throw new JoinedGeometryFailure("Joined nonmanifold edge",new{a=new[]{scope.MinX+(double)xy[edge.A].X/scale,yy[edge.A],scope.MinZ+(double)xy[edge.A].Z/scale},b=new[]{scope.MinX+(double)xy[edge.B].X/scale,yy[edge.B],scope.MinZ+(double)xy[edge.B].Z/scale},faces=list.Select(p=>new{p.Tag,points=new[]{new[]{(double)xy[p.A].X/scale,yy[p.A],(double)xy[p.A].Z/scale},new[]{(double)xy[p.B].X/scale,yy[p.B],(double)xy[p.B].Z/scale},new[]{(double)xy[p.C].X/scale,yy[p.C],(double)xy[p.C].Z/scale}}}).ToArray()});}}
   }
   if(totalArea!=(BigInteger)2048*scale*scale)throw new ArgumentException("Joined finalpositivearea does not cover complete32mcell");var incoming=new Dictionary<int,int>();var outgoing=new Dictionary<int,int>();foreach(var pair in adjacency){var a=pair.Value[0];if(pair.Value.Count==2){var b=pair.Value[1];if(a.A!=b.B||a.B!=b.A||Orient(a.A,a.B,a.C).Sign*Orient(a.A,a.B,b.C).Sign>=0)throw new ArgumentException("Joined inconsistent sharededge/winding");}else{var p=xy[a.A];var q=xy[a.B];if(!((p.X==q.X&&(p.X==0||p.X==32*scale))||(p.Z==q.Z&&(p.Z==0||p.Z==32*scale))))throw new ArgumentException("Joined exposed innergap/hole; no deletion tolerance");incoming.TryGetValue(a.B,out int ii);incoming[a.B]=ii+1;outgoing.TryGetValue(a.A,out int oo);outgoing[a.A]=oo+1;}}if(incoming.Keys.Union(outgoing.Keys).Any(i=>!incoming.ContainsKey(i)||!outgoing.ContainsKey(i)||incoming[i]!=1||outgoing[i]!=1))throw new ArgumentException("Joined boundarybranch/open topology");
   var edges=adjacency.Keys.ToArray();var grid=new Dictionary<(int,int),List<int>>();int refs=0;for(int i=0;i<edges.Length;i++){var a=xy[edges[i].A];var b=xy[edges[i].B];for(int z=(int)Math.Floor((double)Math.Min(a.Z,b.Z)/scale);z<=(int)Math.Floor((double)Math.Max(a.Z,b.Z)/scale);z++)for(int x=(int)Math.Floor((double)Math.Min(a.X,b.X)/scale);x<=(int)Math.Floor((double)Math.Max(a.X,b.X)/scale);x++){if(++refs>4000000)throw new ArgumentException("Joined embedding indexcap");if(!grid.TryGetValue((x,z),out var list))grid[(x,z)]=list=new List<int>();list.Add(i);}}var pairs=new HashSet<(int,int)>();int visits=0;foreach(var list in grid.Values)for(int i=0;i<list.Count;i++)for(int j=i+1;j<list.Count;j++){if((visits&127)==0)cancellation.ThrowIfCancellationRequested();if(++visits>16000000)throw new ArgumentException("Joined embedding rawpaircap");int u=Math.Min(list[i],list[j]),v=Math.Max(list[i],list[j]);if(!pairs.Add((u,v)))continue;if(pairs.Count>4000000)throw new ArgumentException("Joined embedding paircap");var e=edges[u];var f=edges[v];var a=xy[e.A];var b=xy[e.B];var c=xy[f.A];var d=xy[f.B];if(Math.Max(a.X,b.X)<Math.Min(c.X,d.X)||Math.Max(c.X,d.X)<Math.Min(a.X,b.X)||Math.Max(a.Z,b.Z)<Math.Min(c.Z,d.Z)||Math.Max(c.Z,d.Z)<Math.Min(a.Z,b.Z))continue;int abC=Orient(e.A,e.B,f.A).Sign,abD=Orient(e.A,e.B,f.B).Sign,cdA=Orient(f.A,f.B,e.A).Sign,cdB=Orient(f.A,f.B,e.B).Sign;bool shared=e.A==f.A||e.A==f.B||e.B==f.A||e.B==f.B;if(abC==0&&abD==0){bool axis=Math.Abs(b.X-a.X)>=Math.Abs(b.Z-a.Z);long aa=axis?a.X:a.Z,bb=axis?b.X:b.Z,cc=axis?c.X:c.Z,dd=axis?d.X:d.Z;if(Math.Min(Math.Max(aa,bb),Math.Max(cc,dd))>Math.Max(Math.Min(aa,bb),Math.Min(cc,dd)))throw new ArgumentException("Joined exact collinear overlap");}else if(!shared&&abC*abD<=0&&cdA*cdB<=0)throw new ArgumentException("Joined propercrossing/Tjunction");}
